INSERT INTO topics (slug, zhml) VALUES
  ('yi1bian1', E'~ topic #[一边 yi1bian1]\n\nstructure $topic + v. + $topic + v.\n\nmain-trl Indicates two things are being done at the same time.\n\nexamples\n\nexample #1[不要 "bu4 yao4"] #2[$topic] #3[开车 kai1che1] #2[$topic] #4[打电话 "da4 dian4hua4"]。\ntrl *1[Don''t] *4[talk on the phone] *2[while] *3[driving].\n\nend examples'),
  ('verb-reduplication', E'p <em>Verb reduplication</em> is the process in which usually a one-syllable verb is repeated to indicate the brevity or limited scope of the action.\n\nexamples\n\nexample #[你 nǐ] #1[看看 "kan4 kan4"] 。\ntrl *1[Have a look].\n\nexample #1[说说 "shuō shuō"] #2[你的 "ni de"] #3[想法 xiǎngfǎ] 。\ntrl *1[Talk a little bit about] *2[your] *3[opinion].\n\nexample #1[我 wǒ] #2[想 xiǎng] #3[出去 chūqù] #4[走走 "zǒu zǒu"] 。\ntrl *1[I] *4[kind of] *2[want to] *3[go] *4[for a walk].\n\nend examples\n\np The character #[一 yi1] can be inserted between the two instances of the verb.\n\nexamples\n\nexample #1[我 wǒ] #2[可以 kěyǐ] #3[用 yòng] #3[一 yī] #3[用 yòng] #4[你的 "ni de"] #5[电话 diànhuà] #[吗 ma] ？\ntrl *2[Can] *1[I] *3[use] *4[your] *5[phone] *3[just a minute]?\n\nend examples'),
  ('zong3shi4', E'~ t1 #[总是 zong3zhi4]\n~ t2 #[老是 lao3shi4]\n~ mod1 #[这么 zhe4me]\n~ mod2 #[那么 na4me]\n~ mod3 #[很 hen3]\n~ mod4 #[特别 te4bie2]\n\nstructure subject + $t1 + v.\nmain-trl to always do something\n\nexamples\n\nexample #1[他 tā] #2[$t1] #3[一个人 yi2 ge ren2] #6[吃饭 chīfàn] 。\ntrl *1[He] *2[always] *4[eats] *3[alone].\n\nexample #1[我的 wǒ de] #2[学生 xuéshēng] #3[$t1] #4[有 yǒu] #5[很多 hěnduō] #6[有意思 yǒuyìsi] #[的 de] #7[问题 wèntí] 。\ntrl *1[My] *2[students] *3[always] *4[have] *5[a lot of] *6[interesting] *7[questions].\n\nexample #1[不要 bùyào] #2[$t2] #3[笑话 xiàohuà] #4[别人 biérén] 。\ntrl *1[Don''t] *3[laugh at] *4[other people] *2[all the time].\n\nend examples\n\np To use $t1 or t2 with an adj., a modifier such as $mod1, $mod2, $mod3 or $mod4 has to be inserted in between.\n\nexamples\n\nexample #1[别 bié] #2[$t1] #3[不高兴 bù gāoxìng] 。\ntrl *1[Don''t] *2[always] *4[be unhappy].\n\nexample #1[你 nǐ] #2[为什么 wèishéme] #3[$t1] #4[$mod1] #5[忙 máng] ？\ntrl *2[Why] *5[are] *1[you] *3[always] *4[so] *5[busy]?\n\nexample #1[你 nǐ] #2[$t1] #3[$mod1] #4[晚 wǎn] #5[回家 huí jiā] 。\ntrl *1[You] *2[always] *5[come home] *3[so] *4[late].\n\nexample #1[你 nǐ] #2[怎么 zěnme] #3[$t2] #4[$mod1] #5[高兴 gāoxìng] ？\ntrl *2[How] *5[are] *1[you] *3[always] *4[so] *5[happy]?\n\nend examples'),
  ('when', E'~ topic #[时候 shi1hou]\n\nstructure clause + #[的 de] $topic\n\nexamples\n\nexample #1[你不在 "ni3 bu4 zai4"] #[的 de] #2[$topic] ，#3[我 wǒ] #4[会 huì] #5[想 xiǎng] #6[你 nǐ]。\ntrl *3[I] *4[will] *5[miss] *6[you] *2[when] *1[you''re gone].\n\nexample #1[小 xiao3] #[的 de] #2[$topic] ，#3[我 wo3] #4[不 bu4] #5[喜欢 xi3huan] #6[大米 da4mi]。\ntrl *2[When] *1[I was little], *3[I] *4[didn''t] *5[like] *6[rice].\n\nexample #1[我 wǒ] #2[在 zài] #3[中国 zhōngguó] #[的 de] #4[$topic] ，#5[会 hui4] #6[说 shuo1] #7[中文 zhong1wen2]。\ntrl *4[When] *1[I] *2[am in] *3[China], *5[I will] *6[speak] *7[Chinese].\n\nend examples'),
  ('to-only-have', E'~ topic #[就 jiu4]\n\nstructure $topic\nmain-trl to only have\n\np As a <strong>verb</strong>, it means "to only have".\n\nexamples\n\nexample #1[我 wǒ] #2[在 zài] #3[上海 shānghǎi] #4[$topic] #5[两个 "èr ge"] #5[朋友 péngyou] 。\ntrl *1[I] *4[only have] *5[two] *6[friends] *2[in] *3[Shanghai].\n\nend examples\n\np As an <strong>adverb</strong>, it emphasizes earliness of action.\n\nexamples\n\nexample #1[他 tā] #2[$topic] #3[来 lái] 。\ntrl *1[He] *3[will come] *2[right away].\n\nexample #1[他 tā] #2[明天 míngtiān] #3[七点 "qi1 dian3"] #4[$topic] #6[得 děi] #7[上课 "shàng kè"] 。\ntrl *1[He] *6[has to] *7[go to class] at *4[(as early as)] *3[7:00 AM] *2[tomorrow].\n\nexample #1[他 tā] #2[早在 zǎozài] #3[一九四二年 "yījiǔsìèr nian2"] #2[$topic] #4[成 chéng] #5[电影名星 "diànyǐng míngxīng"] #[了 le] 。\ntrl *1[He] *4[had become] *5[a movie star] *2[as early as] *3[1942].\n\nend examples'),
  ('you3-yi1dian3', E'~ topic #[有点儿 "you3 yi1dian3"]\n\nmain-trl a little\n\nexamples\n\nexample #1[我 wǒ] #2[$topic] #3[气 qì] 。\ntrl *1[I]''m *2[a little] *3[angry].\n\nexample #1[我 wǒ] #2[有点儿 "yǒu diǎnr"] #3[饿 è] #[了 le] 。\ntrl *1[I]''m *2[a little] *3[hungry].\n\nexample #1[今天 jīntiān] #2[有点 "yǒu yi1"] #3[冷 lěng] 。\ntrl *1[Today] is *2[a little] *3[cold].\n\nexample #1[我 wǒ] #2[还是 háishi] #3[有点儿 "yǒu diǎnr"] #4[不 bù] #5[明白 míngbai] 。\ntrl *1[I] *2[still] *4[don''t] *3[quite] *5[understand].\n\nexample #1[我 wǒ] #2[只 zhī] #3[会 huì] #4[说 shuō] #5[一点儿 yìdiǎnr] #6[中文 zhōngwén] 。\ntrl *1[I] *3[can] *4[speak] *2[just] *5[a little] *6[Chinese].\n\nend examples'),
  ('yi1zhi2', E'~ topic #[一直 yi1zhi2]\n\nstructure subject + $topic + predicate\nmain-trl constantly, continuously\n\nexamples\n\nexample #1[她 tā] #2[$topic] #3[很 hěn] #4[喜欢 xǐhuan] #5[上海 shànghǎi] 。\ntrl *1[She] *4[has] *2[always] *4[liked] *5[Shanghai] *3[a lot].\n\nexample #1[北京 běijīng] #2[的 de] #3[空气 kōngqì] #4[$topic] #5[很不好 hen3 "bu4 hao3"] 。\ntrl *3[The air] *2[in] *1[Beijing] *4[has been] *5[bad] *4[for a while].\n\nexample #1[他 tā] #2[$topic] #3[一个人 yí ge ren2] #4[住 zhù] ，#5[18岁 "shi2ba1 sui4"] #6[以后 yi3hou4]。\ntrl *6[Since he was] *5[18 years old], *1[he] *4[has] *2[always] *4[lived] *3[alone].\n\nexample #1[昨天 zuótiān] #2[晚上 wǎnshang] #3[从 cóng] #4[7点 "qi1 dian3"] #5[到 dào] #6[10点 "shi2 dian3"] ，#7[我 wo3] #8[$topic] #9[在做 "zai4 zuo4"] #10[作业 zuo4ye4]。\ntrl *3[From] *4[7] *2[PM] *5[to] *6[10] *2[PM] *1[yesterday], *7[I] *9[was] *8[continuously] *9[doing] *10[homework].\n\nend examples'),
  ('to-know', E'~ topic #[懂 dong3]\n\nmain-trl to know or understand\n\nexamples\n\nexample #1[我 wo3] #2[不怎么 bu4] #3[$topic] #4[汉语 han4yu3]。\ntrl *1[I] *2[don''t] *3[know] *4[Chinese] *2[very well].\n\nexample #1[她 ta1] #2[$topic] #3[一些 yi4xie3] #4[德语 de2yu3]。\ntrl *1[She] *2[knows] *3[some] *4[German].\n\nexample #1[$topic] #[的 de] #2[最多 zuìduō] #3[的 de] #4[人 ren2]，#5[说 shuo1] #6[的最少 "de zuìshǎo"]。\ntrl *4[He] *3[who] *1[knows] *2[most] *5[says] *6[least].\n\nend examples'),
  ('bu4-zen3me', E'~ topic #[不怎么 "bu4 zen3me"]\n\nexamples\n\nexample #1[他 tā] #2[$topic] #3[喜欢 xǐhuan] #4[说话 shuōhuà] 。\ntrl *1[He] *2[doesn''t] *3[like] *4[talking] *2[too much].\n\nexample #1[我 wǒ] #2[老公 lǎogōng] #3[$topic] #4[做饭 "zuò fàn"] 。\ntrl *1[My] *2[husband] *3[doesn''t] *4[cook] *3[very often].\n\nend examples\n\np When followed by an adj., it means the same thing as #[不太 "bu4 tai4"].\n\nexamples\n\nexample #1[我 wǒ] #2[觉得 juédé] #3[这个 "zhè ge"] #4[菜 cài] #5[$topic] #6[好吃 hǎochī] 。\ntrl *1[I] *5[don''t] *2[find] *3[this] *4[food] *5[very] *6[tasty].\n\nend examples'),
  ('superlative', E'~ topic #[最 zui4]\n\nstructure $topic + adj. / psychological v. (+ #zh[了 le])\n\nexamples\n\nexample #1[汉语 hànyǔ] #2[是 shì] #3[我 wǒ] #4[知道 zhīdào] #[的 de] #5[$topic] #6[难 nán] #[的 de] #7[语言 yǔyán] 。\ntrl *1[Chinese] *2[is] *5[the most] *6[difficult] *7[language] *3[I] *4[know of].\n\nexample #1[世界 shìjiè] #2[上 shàng] #3[$topic] #3[有钱 yǒuqián] #[的 de] #4[人 rén] #5[是 shì] Elon Musk。\ntrl *3[The richest] *4[person] *2[in] *1[the world] *5[is] Elon Musk.\n\nend examples'),
  ('the-more-the-more', E'~ topic #[越 yue4]\n\nstructure $topic …, $topic …\nmain-trl the more …, the more …\n\nexamples\n\nexample #1[我 wǒ] #2[$topic] #3[想 xiǎng] ，#2[$topic] #4[高兴 gao1xing4]。\ntrl *2[The more] *1[I] *3[thought about it], *4[the happier I was].\n\nexample #1[我 wǒ] #2[$topic] #3[看 kàn] ，#4[$topic] #4[不 bu4] #5[喜欢 xi3huan]。\ntrl *2[The more] *1[I] *3[look at it], *4[the less] *5[I like it].\n\nend examples'),
  ('cong2lai2', E'~ topic #[从来 cong2lai2]\n\nstructure subject + $topic + #3[不 bù] + predicate\n\nmain-trl never\n\nexamples\n\nexample #1[她 tā] #2[$topic] #2[不 bù] #4[喝酒 "hē jiǔ"] 。\ntrl *1[She] *2[never] *3[drinks].\n\nexample #1[你 nǐ] #2[父母 fùmǔ] #3[$topic] #3[不 bù] #4[打 dǎ] #5[你 nǐ] #[吗 ma] ？\ntrl *3[Don''t] *1[your] *2[parents] *3[ever] *4[hit] *5[you]?\n\nend examples\n\np #[来 lai2] can be omitted in casual speech.\n\nexamples\n\nexample #1[我的 "wǒ de"] #2[女朋友 nǚpéngyou] #3[从 cóng] #3[不 bù] #4[给我 "gěi wǒ"] #5[打 dǎ] #6[电话 diànhuà] 。\ntrl *1[My] *2[girlfriend] *3[never] *5[gives] *4[me] *6[a call].\n\nend examples\n\np In the past tense the structure is: subject + $topic + #[没 méi](#[有 yǒu]) + v. + #[过 guo].\n\nexamples\n\nexample #1[很多 hěnduō] #2[中国人 zhōngguórén] #3[$topic] #3[没 méi] #4[出过 "chū guo"] #5[国 guò] 。\ntrl *1[A lot of] *2[Chinese people] *4[have] *3[never] *4[been] *5[abroad].\n\nexample #1[你 nǐ] #2[$topic] #2[没有 "méi yǒu"] #3[想过 "xiǎng guo"] #4[这个 "zhè ge"] #5[问题 wénti] #[吗 ma] ？\ntrl *3[Have] *1[you] *2[never] *3[thought about] *4[this] *5[problem]?\n\nexample #1[她 tā] #2[从来 cónglái] #2[没 méi] #3[见过 "jiàn guo"] #4[她 tā] #5[妈妈 māma] 。\ntrl *1[She] *3[has] *2[never] *3[seen] *4[her] *5[mother].\n\nexample #1[你们 nǐmen] #2[$topic] #2[没有 "méi yǒu"] #3[听说过 "tīngshuō guo"] #4[这个 "zhè ge"] #5[地方 dìfang] #[吗 ma] ？\ntrl *3[Have] *1[you guys] *2[never] *4[heard about] *4[this] *5[place]?\n\nend examples'),
  ('comparison', E'structure A + #[比 bi] + B + adj.\n\nexamples\n\nexample #1[他 tā] (#5[不 bu4]) #2[比 bǐ] #3[我 wǒ] #4[高 gāo] 。\ntrl *1[He]''s *5[(not)] *4[tall]er *2[than] *3[me].\n\nexample #1[这个 "zhè ge"] #2[地方 dìfang] #3[比 bǐ] #4[那个 "nà ge"] #5[地方 dìfang] #6[好 hǎo] 。\ntrl *1[This] *2[place] is *6[better] *3[than] *4[that] *5[place].\n\nexample #1[中文 zhōngwén] #2[比 bǐ] #3[英语 yīngwén] #4[有意思 yǒuyìsi] 。\ntrl *1[Chinese] is more *4[interesting] *2[than] *3[English].\n\nend examples\n\nstructure A + #[跟 gen1] + B + #[一样 yi2yang4] + adj.\n\nexamples\n\nexample #1[你 nǐ] #2[跟 gēn] #3[他 tā] #4[一样 yíyàng] #5[聪明 cōngming] 。\ntrl *1[You]''re *4[as] *5[smart] *2[as] *3[him].\n\nend examples\n\np The negative form uses the structure: A + #[没有 "mei2 you3"] + B + adj.\n\nexamples\n\nexample #1[你 nǐ] #2[没有 "méi yǒu"] #3[他 tā] #4[聪明 cōngming] 。\ntrl *1[You]''re *2[not as] *4[smart] *2[as] *3[him].\n\nexample #1[上海 shànghǎi] #2[没有 "méi yǒu"] #3[北京 běijīng] #4[冷 lěng] 。\ntrl *1[Shanghai] is *2[isn''t as] *4[cold] *2[as] *3[Beijing].\n\nexample #1[这本 "zhè ben3"] #2[书 shū] #3[没有 "méi yǒu"] #4[那本 "nà ben3"] #5[书 shū] #6[有意思 yǒuyìsi] 。\ntrl *1[This] *2[book] is *3[not as] *6[interesting] *3[as] *4[that] *5[book].\n\nend examples'),
  ('zhen1de', E'~ topic #[真的 zhen1de]\n\nmain-trl really\n\nexamples\n\nexample #1[我 wǒ] #2[$topic] #3[爱 ài] #4[她 tā] 。\ntrl *1[I] *2[really] *3[love] *4[her].\n\nexample #1[我 wǒ] #2[$topic] #3[不 bù] #4[知道 zhīdào] 。\ntrl *1[I] *2[really] *3[don''t] *4[know].\n\nexample #1[他的 tā de] #2[音乐 yīnyuè] #3[$topic] #[很 hěn] #4[棒 bàng] 。\ntrl *1[His] *2[music] *4[is] *3[really] *4[amazing].\n\nend examples'),
  ('tai4-le', E'~ t1 #[太 tai4]\n~ t2 #[了 le]\n\nstructure $t1 + adj. + $t2\n\nmain-trl overly\n\nexamples\n\nexample #1[米饭 mi3fan4] #2[$t1] #3[多 duo1] #2[$t2]\ntrl *3[There''s] *2[too much] *1[rice].\n\nexample #1[这个 "zhe4 ge"] #2[地方 di4fang] #3[$t1] #4[有意思 you3yi4si] #3[$t2]。\ntrl *1[This] *2[place] is *3[extremely] *4[interesting].\n\nexample #1[你 ni3] #2[$t1] #3[好 hao3] #2[$t2]。\ntrl *1[You]''re *2[so] *3[great].\n\nend examples'),
  ('not-too-not-very', E'~ topic #[不太 "bu4 tai4"]\n\nstructure $topic + adj.\n\nexamples\n\nexample #1[我 wǒ] #2[家 jiā] #3[$topic] #4[大 dà] 。\ntrl *1[My] *2[house] *3[isn''t too] *4[big].\n\nexample #1[我 wǒ] #2[觉得 jue1de] #3[他 tā] #4[$topic] #5[聪明 cong1ming] 。\ntrl *1[I] *4[don’t] *2[think] *3[he]''s *4[very] *5[smart].\n\nend examples'),
  ('qilai', E'~ topic #[起来 qilai]\n\nstructure subject + v. + $topic + adj.\n\nexamples\n\nexample #1[這个 "zhè ge"] #2[包 bāo] #3[提 tí] #[$topic] #[很 hěn] #4[重 zhòng] 。\ntrl *1[This] *2[bag] *4[is heavy] (“*3[lifts] *4[heavy]”).\n\nexample #1[他 tā] #2[看 kàn] #[$topic] #[很 hěn] #3[累 lèi] 。\ntrl *1[He] *2[looks] *3[tired].\n\nexample #1[她的 "tā de"] #2[话 huà] #3[听 tīng] #[$topic] #[很 hěn] #4[怪 guài] 。\ntrl *1[Her] *2[words] *3[sounded] *4[strange].\n\nend examples'),
  ('si3-le', E'~ topic #[死了 "si3 le"]\n\nstructure subject + pejorative adj. + $topic\n\nmain-trl so, terribly, to death\n\nexamples\n\nexample #1[热 re4] / #2[冷 leng3] $topic！\ntrl The weather is so *1[hot] / *2[cold]!\n\nexample #1[我饿 "wo3 e4"] #2[$topic]。\ntrl *2[I''m] *1[so] *2[hungry].\n\nexample #[吵 chao3] $topic！\ntrl What a ruckus!\n\nend examples\n\np $topic is a degree complement. A degree complement usually follows an adjective which it intensifies or modifies.')
